// The DINOv2 ViT encoder of FoundationStereo's Depth Anything branch
// (`dinov2_vitl14`'s `get_intermediate_layers`), at reduced width, against
// `DinoVisionTransformer` in FP64.
//
// Seeded random weights (layer scales and LayerNorm affines randomised). One model
// keeps vitl14's 37x37 position grid and shrinks it, the other enlarges a 4x4 grid,
// so both directions of the bicubic `interpolate_pos_encoding` are covered. Fixtures
// generated by tests/fixtures/dinov2/generate.py.
//
// Runs on whichever backend teeny-runtime was built for: CUDA, or RISC-V under qemu
// (`--no-default-features --features qemu`, with
// `TEENYC_QEMU_RISCV64=/usr/bin/qemu-riscv64-static` if only the static qemu exists).

#![cfg(any(feature = "cuda", feature = "qemu"))]

mod common;

use common::stereo_block::check_block;
use serial_test::serial;
use teeny_core::name_scope::name_scope;
use vision_rs::models::stereo::feature::dinov2::{VitDims, encoder};

/// 64 wide, 3 blocks of 4 heads, 37x37 position grid, 56x84 image (4x6 patches);
/// blocks 0 and 2.
#[test]
#[serial]
fn vit_encoder_shrunk_pos_grid_matches_dinov2() -> anyhow::Result<()> {
    let dims = VitDims {
        dim: 64,
        depth: 3,
        heads: 4,
        mlp: 256,
        patch: 14,
        pos_grid: 37,
    };
    check_block(
        "dinov2/vit_down",
        "dinov2/vit_down",
        &[("x", &[1, 3, 56, 84])],
        |i| {
            let _p = name_scope("pretrained");
            let [l0, l2]: [_; 2] = match encoder::<f32>(&dims, &i[0], (56, 84), &[0, 2]).try_into()
            {
                Ok(v) => v,
                Err(_) => unreachable!(),
            };
            vec![("l0", l0), ("l2", l2)]
        },
        1e-4,
    )?;
    Ok(())
}

/// 48 wide, 1 block of 3 heads, 4x4 position grid, 98x140 image (7x10 patches).
#[test]
#[serial]
fn vit_encoder_enlarged_pos_grid_matches_dinov2() -> anyhow::Result<()> {
    let dims = VitDims {
        dim: 48,
        depth: 1,
        heads: 3,
        mlp: 192,
        patch: 14,
        pos_grid: 4,
    };
    check_block(
        "dinov2/vit_up",
        "dinov2/vit_up",
        &[("x", &[1, 3, 98, 140])],
        |i| {
            let _p = name_scope("pretrained");
            let mut out = encoder::<f32>(&dims, &i[0], (98, 140), &[0]);
            vec![("l0", out.remove(0))]
        },
        1e-4,
    )?;
    Ok(())
}

/// The whole ViT-L (24 blocks) with a real FoundationStereo checkpoint's
/// `feature.dino.depth_anything.pretrained` weights, on the sample left image as
/// `Feature.forward` resizes it for the branch (224x336, 16x24 patches), returning
/// Depth Anything V2's layers 4, 11, 17 and 23, against DINOv2 in FP64. Outputs reach
/// ~75, so the tolerance is absolute 5e-3 (~7e-5 relative). Build the
/// fixtures with tests/fixtures/dinov2/gen_real.py, point `FS_REAL_FIXTURES` at the
/// directory holding `dinov2_real/` and run with `--ignored`.
#[test]
#[serial]
#[ignore = "needs FS_REAL_FIXTURES (real-checkpoint fixtures, not committed)"]
fn vit_encoder_matches_real_checkpoint() -> anyhow::Result<()> {
    let root = std::env::var("FS_REAL_FIXTURES")
        .expect("set FS_REAL_FIXTURES to the real-checkpoint fixture directory");
    let dir = format!("{root}/dinov2_real");
    let dims = VitDims::vitl14();
    check_block(
        "dinov2_real",
        &dir,
        &[("x", &[1, 3, 224, 336])],
        |i| {
            let _p = name_scope("pretrained");
            let [l4, l11, l17, l23]: [_; 4] =
                match encoder::<f32>(&dims, &i[0], (224, 336), &VitDims::VITL_LAYERS).try_into() {
                    Ok(v) => v,
                    Err(_) => unreachable!(),
                };
            vec![("l4", l4), ("l11", l11), ("l17", l17), ("l23", l23)]
        },
        5e-3,
    )?;
    Ok(())
}
